document.addEventListener("alpine:init",()=>{let n=localStorage.getItem("sn-support-frontend-theme")??getComputedStyle(document.documentElement).getPropertyValue("--default-theme-mode");window.Alpine.store("snSupportFrontendTheme",n==="dark"||n==="system"&&window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"),window.addEventListener("sn-support-frontend-theme-changed",e=>{let t=e.detail;localStorage.setItem("sn-support-frontend-theme",t),t==="system"&&(t=window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"),window.Alpine.store("snSupportFrontendTheme",t)}),window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change",e=>{localStorage.getItem("sn-support-frontend-theme")==="system"&&window.Alpine.store("snSupportFrontendTheme",e.matches?"dark":"light")}),window.Alpine.effect(()=>{window.Alpine.store("snSupportFrontendTheme")==="dark"?document.documentElement.classList.add("dark"):document.documentElement.classList.remove("dark")})});document.addEventListener("alpine:init",()=>{});
